import { and, eq, isNull, notInArray } from \"drizzle-orm\";
import { getDb, milestones, issues } from \"@/server/db\";
import { newId } from \"@/lib/id\";
import { MilestoneStateError } from \"@/lib/milestones\";
import { MAX_OPEN_MILESTONES_PER_PROJECT } from \"@/config/constants\";
import { toIsoTimestamp } from \"@/types/common\";
import type { OrgId, ProjectId, MilestoneId, IssueId } from \"@/types/common\";
import type { Milestone, MilestoneWithProgress } from \"@/types/milestone\";
import type { CreateMilestoneInput, UpdateMilestoneInput } from \"@/schemas/milestone\";

function map(row: typeof milestones."'$inferSelect): Milestone {
  const { normalizedName: _, ...value } = row;
  return value as Milestone;
}
export function findMilestone(orgId: OrgId, id: MilestoneId): Milestone | null {
  const row = getDb().select().from(milestones).where(and(eq(milestones.orgId, orgId), eq(milestones.id, id))).get();
  return row ? map(row) : null;
}
export function list(orgId: OrgId, projectId: ProjectId): Milestone[] {
  return getDb().select().from(milestones).where(and(eq(milestones.orgId, orgId), eq(milestones.projectId, projectId))).all().map(map);
}
function checkName(orgId: OrgId, projectId: ProjectId, name: string, except?: MilestoneId) {
  if (list(orgId, projectId).some(m => m.id !== except && m.name.trim().toLowerCase() === name.trim().toLowerCase()))
    throw new MilestoneStateError("name_taken");
}
function checkCap(orgId: OrgId, projectId: ProjectId) {
  if (list(orgId, projectId).filter(m => m.closedAt === null).length >= MAX_OPEN_MILESTONES_PER_PROJECT)
    throw new MilestoneStateError("too_many_open");
}
export function create(input: CreateMilestoneInput): Milestone {
  return getDb().transaction(tx => {
    checkName(input.orgId, input.projectId, input.name);
    checkCap(input.orgId, input.projectId);
    const stamp = toIsoTimestamp(new Date());
    return map(tx.insert(milestones).values({ ...input, id: newId(), normalizedName: input.name.trim().toLowerCase(), createdAt: stamp, updatedAt: stamp }).returning().get());
  });
}
export function update(before: Milestone, input: UpdateMilestoneInput): Milestone {
  return getDb().transaction(tx => {
    if (input.name !== undefined) checkName(before.orgId, before.projectId, input.name, before.id);
    return map(tx.update(milestones).set({
      ...(input.name === undefined ? {} : { name: input.name, normalizedName: input.name.trim().toLowerCase() }),
      ...(input.targetDate === undefined ? {} : { targetDate: input.targetDate }),
      updatedAt: toIsoTimestamp(new Date()),
    }).where(and(eq(milestones.orgId, before.orgId), eq(milestones.id, before.id))).returning().get());
  });
}
export function reopen(before: Milestone): Milestone {
  return getDb().transaction(tx => {
    const current = findMilestone(before.orgId, before.id)!;
    if (current.closedAt === null) throw new MilestoneStateError("already_open");
    checkCap(before.orgId, before.projectId);
    return map(tx.update(milestones).set({ closedAt: null, updatedAt: toIsoTimestamp(new Date()) }).where(eq(milestones.id, before.id)).returning().get());
  });
}
export function close(before: Milestone, target: MilestoneId | null): { milestone: Milestone; movedIssueIds: readonly IssueId[] } {
  return getDb().transaction(tx => {
    if (findMilestone(before.orgId, before.id)!.closedAt !== null) throw new MilestoneStateError("closed");
    const stamp = toIsoTimestamp(new Date());
    const moved = tx.update(issues).set({ milestoneId: target, updatedAt: stamp }).where(and(
      eq(issues.orgId, before.orgId), eq(issues.projectId, before.projectId),
      eq(issues.milestoneId, before.id), isNull(issues.archivedAt), notInArray(issues.status, ["done", "canceled"]),
    )).returning({ id: issues.id }).all();
    const milestone = map(tx.update(milestones).set({ closedAt: stamp, updatedAt: stamp }).where(eq(milestones.id, before.id)).returning().get());
    return { milestone, movedIssueIds: moved.map(r => r.id as IssueId) };
  });
}
export function withProgress(milestone: Milestone, now: number): MilestoneWithProgress {
  const rows = getDb().select({ status: issues.status }).from(issues).where(and(eq(issues.orgId, milestone.orgId), eq(issues.milestoneId, milestone.id), isNull(issues.archivedAt))).all();
  const closed = rows.filter(r => r.status === "done" || r.status === "canceled").length;
  const progress = { total: rows.length, closed, open: rows.length - closed };
  return { milestone, progress, overdue: milestone.closedAt === null && milestone.targetDate !== null && new Date(milestone.targetDate).getTime() < now && progress.open > 0 };
}
