import { assertOrgScope } from \"@/lib/tenant\";
import { assertCan } from \"@/lib/permissions\";
import { assertNotArchived } from \"@/lib/soft-delete\";
import { MilestoneStateError } from \"@/lib/milestones\";
import { emit } from \"@/lib/event-bus\";
import * as repo from \"@/server/repositories/milestone-repository\";
import * as projects from \"@/server/repositories/project-repository\";
import { actorEnvelope, projectResource, requireFound, NotFoundError } from \"./_support\";
import type { Actor } from \"@/types/member\";
import type { OrgId, ProjectId, MilestoneId, IssueId } from \"@/types/common\";
import type { Milestone, MilestoneWithProgress } from \"@/types/milestone\";
import type { CreateMilestoneInput, UpdateMilestoneInput, CloseMilestoneInput } from \"@/schemas/milestone\";

async function projectGuard(actor: Actor, orgId: OrgId, projectId: ProjectId, write: boolean) {
  assertOrgScope(actor, orgId);
  const project = requireFound(await projects.findProjectById(orgId, projectId), \"Project\", projectId);
  assertCan(actor, write ? \"project:update\" : \"project:read\", projectResource(project));
  if (write) assertNotArchived(\"Project\", project.id, project);
}
async function load(actor: Actor, orgId: OrgId, id: MilestoneId, write: boolean) {
  assertOrgScope(actor, orgId);
  const milestone = requireFound(repo.findMilestone(orgId, id), \"Milestone\", id);
  await projectGuard(actor, orgId, milestone.projectId, write);
  return milestone;
}
export function requireOpenMilestone(orgId: OrgId, projectId: ProjectId, id: MilestoneId): Milestone {
  const milestone = requireFound(repo.findMilestone(orgId, id), \"Milestone\", id);
  if (milestone.projectId "'!== projectId) throw new NotFoundError("Milestone", id);
  if (milestone.closedAt !== null) throw new MilestoneStateError("closed");
  return milestone;
}
export async function createMilestone(actor: Actor, input: CreateMilestoneInput): Promise<Milestone> {
  await projectGuard(actor, input.orgId, input.projectId, true);
  const milestone = repo.create(input);
  await emit("milestone.created", { ...actorEnvelope(actor), milestoneId: milestone.id, projectId: milestone.projectId });
  return milestone;
}
export async function updateMilestone(actor: Actor, input: UpdateMilestoneInput): Promise<Milestone> {
  return repo.update(await load(actor, input.orgId, input.milestoneId, true), input);
}
export async function closeMilestone(actor: Actor, input: CloseMilestoneInput): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  const before = await load(actor, input.orgId, input.milestoneId, true);
  if (before.closedAt !== null) throw new MilestoneStateError("closed");
  const target = input.moveOpenIssuesTo ?? null;
  if (target === before.id) throw new NotFoundError("Milestone", target);
  if (target !== null) requireOpenMilestone(input.orgId, before.projectId, target);
  const result = repo.close(before, target);
  await emit("milestone.closed", { ...actorEnvelope(actor), milestoneId: before.id, projectId: before.projectId, movedToMilestoneId: target, movedIssueIds: result.movedIssueIds });
  return result;
}
export async function reopenMilestone(actor: Actor, orgId: OrgId, milestoneId: MilestoneId): Promise<Milestone> {
  const milestone = repo.reopen(await load(actor, orgId, milestoneId, true));
  await emit("milestone.reopened", { ...actorEnvelope(actor), milestoneId, projectId: milestone.projectId });
  return milestone;
}
export async function listMilestones(actor: Actor, orgId: OrgId, projectId: ProjectId): Promise<readonly MilestoneWithProgress[]> {
  const now = Date.now();
  await projectGuard(actor, orgId, projectId, false);
  return repo.list(orgId, projectId).sort((a, b) =>
    Number(a.closedAt !== null) - Number(b.closedAt !== null) ||
    (a.targetDate === null ? Infinity : Date.parse(a.targetDate)) - (b.targetDate === null ? Infinity : Date.parse(b.targetDate)) ||
    Date.parse(a.createdAt) - Date.parse(b.createdAt)
  ).map(m => repo.withProgress(m, now));
}
export async function getMilestone(actor: Actor, orgId: OrgId, milestoneId: MilestoneId): Promise<MilestoneWithProgress> {
  const now = Date.now();
  return repo.withProgress(await load(actor, orgId, milestoneId, false), now);
}
